  "explain": "📖 교재 근거:\n| 친유성/친수성 | 기름에 잘 녹음 / 물에 잘 녹음. 계면활성제는 두 특성 모두 보유. |\n해설: HLB는 친수성과 친유성 비율을 수치화한 값으로 높을수록 친수성을 나타내며, 3~6 범위는 W/O 유화, 8~18 범위는 O/W 유화에 사용됩니다. 따라서 HLB 값이 1~3 범위인 계면활성제가 주로 세정제로 사용된다고 설명한 ③번은 옳지 않습니다.",
