  "explain": "📖 교재 근거:\n| 행정처분의 경감 또는 면제 | • 회수 계획량의 5분의 4 이상을 회수한 경우: 행정처분 면제<br>• 회수 계획량의 3분의 1 이상을 회수한 경우:<br>  - 행정처분 기준이 등록 취소라면 업무정지 2개월 이상 6개월 이하 범위에서 처분<br>  - 행정처분 기준이 업무정지 또는 품목의 제조·수입·판매 업무정지라면 정지 처분 기간의 3분의 2 이하의 범위에서 경감<br>• 회수 계획량의 4분의 1 이상 3분의 1 미만을 회수한 경우:<br>  - 행정처분 기준이 등록 취소라면 업무정지 3개월 이상 6개월 이하 범위에서 처분<br>  - 행정처분 기준이 업무정지 또는 품목의 제조·수입·판매 업무정지라면 정지 처분 기간의 2분의 1 이하의 범위에서 경감 |\n해설: 화장품법상 위해화장품 공표 명령 등 관련 의무를 위반했을 때의 행정처분 기준은 1차 위반 시 '판매업무정지 3개월'이 적용되므로 정답은 ②입니다. 따라서 1차 위반 처분을 경고(①), 판매업무정지 1개월(③), 판매업무정지 6개월(④), 등록 취소(⑤)로 제시한 선지들은 모두 옳지 않습니다.",
