  "explain": "📖 교재 근거:\n| 자외선 차단 | 징크옥사이드, 티타늄디옥사이드(물리적) / 벤조페논-3, 에칠헥실메톡시신나메이트(화학적) | 최대 25% / 7.5% 등 | 로션, 크림, 오일 등 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 기능성화장품 심사 규정에 따르면 자외선 차단 성분인 에칠헥실메톡시신나메이트의 최종 제품 내 사용 한도는 7.5% 이하이므로 정답은 ④입니다. 따라서 3.0% 이하, 5.0% 이하, 10.0% 이하, 25.0% 이하를 제시한 ①, ②, ③, ⑤는 옳지 않습니다.",
