  "explain": "📖 교재 근거:\n⑦ 제조 구역별 청소 및 위생관리 절차에 따라 효능이 입증된 세척제 및 소독제를 사용해야 한다.\n해설: 제조 구역별 위생관리 절차에 따라 효능이 입증된 세척제 및 소독제를 사용하여 오염을 방지해야 하므로, '세척제 및 소독제의 가격'은 세척 및 소독 주기를 설정할 때 고려할 사항으로 적합하지 않아 ③이 정답입니다. 반면 설비의 사용 빈도, 제형, 연속 제조 시간 등은 제품의 품질과 오염 방지에 영향을 미치는 요소이므로 주기 설정 시 고려해야 하는 적합한 사항입니다.",
