  "explain": "📖 교재 근거:\n| 탈모 완화 | 덱스판테놀, 비오틴, 엘-멘톨, 징크피리치온 | 고시 규격 참조 | — |\n해설: 근거 구절에 따르면 탈모 완화 기능성화장품의 고시 성분은 덱스판테놀, 비오틴, 엘-멘톨, 징크피리치온이므로, 여기에 해당하지 않는 나이아신아마이드가 정답입니다. 반면 엘-멘톨, 비오틴, 덱스판테놀은 탈모 완화 고시 성분에 해당합니다.",
