  "explain": "📖 교재 근거:\n| 과산화수소 및 과산화수소 생성 물질 | 두발용 제품류에 과산화수소로서 3.0% / 손톱 경화용 제품에 과산화수소로서 2.0% / ※ 기타 제품에는 사용금지 |\n해설: 과산화수소는 두발용 제품류에 3.0% 한도로 배합 기준이 명시되어 있어 산화 염모제 제2제의 성분으로 사용되므로 ⑤가 정답입니다. 반면 ① 정제수, ② 암모니아, ③ 에탄올아민, ④ 치오글라이콜릭애씨드는 제시된 두발용 제품류의 해당 성분 기준에 제시되어 있지 않으므로 오답입니다.",
