  "explain": "📖 교재 근거:\n| 아이오도프로피닐부틸카바메이트(IPBC) `🎯 기출` | 사용 후 씻어내는 제품에 0.02% / 사용 후 씻어내지 않는 제품에 0.01% / 다만, 데오드란트에 배합할 경우에는 0.0075% | 입술에 사용되는 제품, 에어로졸(스프레이에 한함) 제품, 바디로션 및 바디크림에는 사용금지 / 영유아용 제품류 또는 13세 이하 어린이가 사용할 수 있음을 특정하여 표시하는 제품에는 사용금지(목욕용 제품, 샤워젤류 및 샴푸류는 제외) |\n해설: 정답은 ②번 살리실릭애씨드(0.5% 이하)입니다. 오답 선지 중 ③번의 메칠이소치아졸리논은 사용 후 씻어내는 제품에 0.0015% 한도로만 허용되므로 0.1% 이하는 옳지 않습니다.",
