  "explain": "📖 교재 근거:\n| 나등급 (위해 기준) | • 안전용기·포장 기준을 위반한 경우<br>• 유통화장품 안전관리 기준에 적합하지 않은 경우(기능성화장품의 기능성을 나타나게 하는 주원료 함량이 기준치에 부적합한 경우는 제외함) |\n해설: 유통화장품 안전관리 기준에 적합하지 않은 경우는 위해성 등급 중 '나등급'에 해당하므로 ⑤번이 정답입니다. 반면 화장품에 사용할 수 없는 원료를 사용한 경우(③번)는 '가등급'에 해당하며, 나머지 선지들 역시 제시된 나등급 기준에 부합하지 않습니다.",
