  "explain": "📖 교재 근거:\n| 광범위 방부 효과 | 여러 종류의 미생물과 넓은 온도 및 pH 범위에서 방부 효과가 있어야 함 |\n해설: 보존제는 넓은 온도 및 pH 범위에서 방부 효과가 있어야 한다는 조건을 갖추어야 하므로, 비교적 넓은 pH 범위(3.0 ~ 10.0)에서 안정하며 열에 강하다는 ②번이 옳습니다. 따라서 고온에서 쉽게 분해되거나 특정 산성 영역에서만 활성을 띤다는 등의 설명은 보존제가 갖추어야 할 광범위 방부 조건에 부합하지 않습니다.",
