  "explain": "📖 교재 근거:\n| 대표적인 오염균 | 황색포도상구균, 대장균, 녹농균 | 빵 효모, 칸디다균 | 푸른곰팡이, 맥아곰팡이 |\n해설: 제시된 자료에 따르면 황색포도상구균, 녹농균, 칸디다균, 대장균(②, ③, ④, ⑤)은 대표적인 오염균으로 명시되어 있습니다. 반면 유산균(Lactobacillus)은 해당 대표 오염균에 포함되어 있지 않으므로 방부력 효능 평가 시험의 대표적인 지표 미생물이 아닙니다.",
