  "explain": "📖 법령 근거:\n| 알루미늄 및 그 염류 함유 제품(체취방지용 제품류에 한함) | 신장 질환이 있는 사람은 사용 전에 의사, 약사, 한의사와 상의할 것 |\n해설: 알루미늄 및 그 염류를 함유한 체취방지용 제품류에는 '신장 질환이 있는 사람은 사용 전에 의사, 약사, 한의사와 상의할 것'을 표시해야 하므로 ⑤가 정답입니다. 반면 '3세 이하 영유아에게는 사용하지 말 것'(②)은 살리실릭애씨드나 IPBC 함유 제품 등에, '사용 시 흡입되지 않도록 주의할 것'(③)은 스테아린산아연 함유 파우더 제품에 표시해야 하는 문구입니다.",
