  "explain": "📖 법령 근거:\n해설: 정답은 ⑤번으로, CGMP 기준상 원자재 수입 검사 시 급한 생산 일정을 이유로 시험 결과 확인 전에 출고 승인을 진행할 수 없습니다. 따라서 시험 결과가 나오기 전에 출고 승인을 진행할 수 있다고 설명한 ⑤번은 옳지 않습니다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
