  "explain": "📖 교재 근거:\n| 이미다졸리디닐우레아(3,3'-비스(1-히드록시메칠-2,5-디옥소이미다졸리딘-4-일)-1,1'메칠렌디우레아) | Imidazolidinyl Urea | 방부제 | - | 이미다졸리디닐우레아는 화장품의 변질을 막는 방부제로, 0.6%까지 사용이 제한된 성분입니다. | - | 0.6% | 방부·보존 | 중빈도 | 기타 제품에는 사용금지 | - |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: '이미다졸리디닐우레아'는 화장품의 변질을 막는 방부제로 0.6%까지 배합 한도가 제한되어 있으므로 ①이 정답입니다. 따라서 0.3% 이하, 0.5% 이하, 0.1% 이하, 1.0% 이하로 제시된 나머지 선지(②, ③, ④, ⑤)는 옳지 않습니다.",
