    "id": "ㄱ",
    "sid": "manufacturing_st_385ad5",
    "conceptId": "§1.1",
    "text": "CMC 이상의 농도에서 계면활성제 분자들이 스스로 회합하여 미셀(Micelle)을 형성하기 시작한다.",
