  "derivedFrom": "subject2_q42",
  "explain": "📖 교재 근거 (L41):\n② 계면활성제 → HLB 값에 따른 용도 구분 (3~6 W/O, 8~18 O/W)\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 계면활성제의 HLB 값이 8~18일 때 O/W형(수중유형) 에멀션 제조에 적절하므로, 이 범위에 해당하는 ③번이 정답입니다. 반면 ②번의 HLB 3~6은 W/O형 에멀션 제조에 사용되는 범위이므로 옳지 않습니다.",
