  "derivedFrom": "subject2_q45",
  "explain": "📖 교재 근거:\n| 밀폐제(필름 형성제) | 피지처럼 피부 표면에 얇은 소수성 피막을 형성하여 수분 증발을 억제하는 성분으로 TEWL(경피수분손실도)를 저하시키며 피막형성제라고도 불림 |\n해설: 밀폐제는 피부 표면에 얇은 소수성 피막을 형성하여 수분 증발을 억제하고 경피수분손실(TEWL)을 저하시키는 역할을 하므로 ④가 정답입니다. 수분과 결합하여 피부 수분을 증가시키는 메커니즘은 습윤제에 해당하며, 콜라겐 합성 촉진이나 세포 분열 촉진 등은 밀폐제의 설명으로 올바르지 않습니다.",
