  "derivedFrom": "subject2_q47",
  "explain": "📖 법령 근거:\n3. 설비 등은 제품의 오염을 방지하고 배수가 용이하도록 설계, 설치하며, 제품 및 청소 소독제와 화학반응을 일으키지 않을 것\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 설비가 설계한 명세서대로 제작 및 설치되었는지 검증하는 단계는 설치적격성평가(IQ)에 해당하므로 정답은 ①번입니다. 따라서 설계적격성평가(DQ), 운전적격성평가(OQ), 성능적격성평가(PQ), 공정밸리데이션(PV)은 설비의 제작 및 설치 상태를 검증하는 단계가 아니므로 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
  "answer": "1"
