  "explain": "📖 법령 근거:\n해설: 품질시험 결과 부적합 판정을 받은 원료를 생산부서장의 임의 승인 하에 재작업용 원료로 바로 투입하는 것은 올바른 처리 절차가 아니므로 ③번이 정답입니다. 부적합 판정 시에는 라벨 부착 및 격리 보관, 원인 규명을 위한 일탈 조사, 반품 또는 폐기 절차 등을 따라야 합니다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
