  "explain": "📖 교재 근거 (L2075):\n| 미세플라스틱 | 세정, 각질 제거 등의 제품에 남아 있는 5mm 이하의 고체플라스틱으로, 유통화장품 안전성 기준상 배합 금지 성분 |\n해설: 유통화장품 안전성 기준상 배합 금지 성분으로 규정된 미세플라스틱은 ‘세정, 각질 제거 등의 제품에 남아 있는 5mm 크기 이하의 고체플라스틱’으로 정의되므로 ③이 정답입니다. 따라서 크기 기준을 10mm 이하로 표기한 ①번이나 용기 재질, 실리콘 막, 액상 고분자 등을 제시한 선지들은 모두 옳지 않습니다.",
