  "explain": "📖 교재 근거:\n| 부틸메톡시디벤조일메탄 | Butyl Methoxydibenzoylmethane | 자외선 차단제 | - | 유상층에 용해되어 자외선 흡수에 관여하며, 사용 제한이 있는 자외선 차단 관련 성분입니다. | - | 5.0% | 홍조, 색소침착 | 고빈도 | UVA 차단 | - |\n해설: 선지 ④의 아보벤존(부틸메톡시디벤조일메탄)은 UVA를 차단하는 자외선 흡수 성분이므로 오답입니다. 따라서 자외선 B(UVB)를 차단하는 대표적인 유기 자외선 차단제 성분은 ⑤ 에칠헥실메톡시신나메이트입니다.",
