  "derivedFrom": "subject2_q53",
  "explain": "📖 교재 근거:\n```mermaid\nflowchart LR\nP[\"페녹시에탄올<br/>보존제\"] -->|\"1.0% 이하\"| L1[\"최종 제품\"]\nB[\"벤조익애씨드<br/>보존제\"] -->|\"0.5% 이하\"| L2[\"씻어내지 않는 제품\"]\nS[\"살리실산\"] -->|\"0.5% 이하\"| L3[\"영유아용 사용금지<br/>(씻어내는 제품 제외)\"]\nT[\"티타늄디옥사이드<br/>자외선차단제\"] -->|\"25.0% 이하\"| L4[\"최종 제품\"]\n```\n해설: 제공된 정답에 따라 무기 자외선 차단제 성분인 '징크옥사이드'의 최종 제품 내 사용 한도는 25.0% 이하이므로 ③이 정답입니다. 따라서 5.0% 이하, 10.0% 이하, 20.0% 이하, 15.0% 이하로 제시된 나머지 선지들은 올바른 사용 한도가 아니므로 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
  "answer": "3"
