  "derivedFrom": "subject2_q54",
  "explain": "📖 교재 근거:\n| 안전역 | 화장품에 존재하는 위해요소의 최대 무독성 용량을 일일 인체노출량으로 나눈 값 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 유해 물질이 인체에 노출되었을 때 독성이 관찰되지 않는 최대 투여량을 뜻하는 용어는 최대무작용량을 나타내는 ⑤ NOAEL입니다. 따라서 LOAEL(최소영향관찰용량), ADI(1일섭취허용량), LD50(반수치사량), LC50(반수치사농도)은 독성이 관찰되지 않는 최대 투여량에 해당하지 않아 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
