  "derivedFrom": "subject2_q61",
  "explain": "📖 법령 근거 (L3454):\n해설: 화장품책임판매업자가 유통 화장품의 안전성 문제로 제품을 회수할 때 작성해야 하는 서류에 ③ ‘생산원가 손실 보고서’는 해당하지 않아 정답입니다. 반면 ① 회수계획서, ② 회수종합보고서, ④ 회수이행성적서, ⑤ 회수사실 공표문은 회수 업무와 관련된 서류에 해당하므로 옳지 않은 선지입니다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
