  "explain": "📖 교재 근거 (L1824):\n> 한 줄 요약: CGMP 4대 기준서(제품표준서·제조관리·품질관리·제조위생관리) + 원료품질성적서 구비.\n해설: 우수화장품 제조 및 품질관리 기준(CGMP)의 4대 기준서는 제품표준서, 제조관리기준서, 품질관리기준서, 제조위생관리기준서입니다. 따라서 ①, ②, ③, ④는 모두 4대 기준서에 해당하며, ⑤ 유통관리기준서는 이에 포함되지 않습니다.",
