  "explain": "📖 교재 근거:\n⑧ 다음의 경우는 처분을 2분의 1까지 감경하거나 면제할 수 있다.\n해설: 행정처분 기준에 따라 처분을 감경하거나 면제할 수 있으므로 옳은 설명은 ④번입니다. 따라서 처분을 전혀 감면할 수 없다거나 10% 감경, 특정 형벌 및 과태료만 면제된다고 한 나머지 선지(①, ②, ③, ⑤)는 옳지 않습니다.",
