  "explain": "📖 교재 근거:\n| 장벽대체제 | 각질층 내 세포간지질(세라마이드, 지방산, 콜레스테롤) 성분으로 보습제 성분으로 처방하여 피부장벽 기능의 유지와 회복에 관여함으로써 피부 보습력 유지를 증가시킴 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 각질층 내 세포간지질의 3대 핵심 성분인 세라마이드, 콜레스테롤, 유리지방산의 가장 이상적인 비율은 3 : 1 : 1이므로 ①이 정답입니다. 따라서 다른 비율을 제시한 ②, ③, ④, ⑤는 올바른 비율이 아니므로 오답입니다.",
