  "explain": "📖 교재 근거 (restricted_ingredients):\n| 징크옥사이드 | Zinc Oxide | 자외선 차단제 | - | 자외선 차단제로 유상층에 용해되어 활용되며, 최대 25%까지 사용 가능한 사용 제한 원료입니다. | - | 25% | 홍조, 색소침착 | 고빈도 | 무기 자외선 차단제, 최대 함량 25% | - |\n해설: 징크옥사이드는 최대 25%까지 배합 가능한 무기 자외선 차단제 성분입니다. 반면 아보벤존, 살리실산, 나이아신아마이드, 레티놀 등은 무기 자외선 차단제에 해당하지 않습니다.",
