  "explain": "📖 법령 근거 (L59):\n(5) 광독성 및 광감작성 시험자료(자외선에서 흡수가 없음을 입증하는 흡광도 시험자료를 제출하는 경우에는 면제함)\n해설: 광독성 및 광감작성 시험은 자외선 흡수와 관련된 시험 규정에서 알 수 있듯이 햇빛(자외선)에 노출되었을 때 유발되는 독성 및 자극을 평가하는 시험이므로 정답은 ④입니다. 반면 안점막자극 시험(①) 등은 점막 자극 등을 평가하는 자료이므로 자외선 노출에 따른 독성을 평가하는 시험에 해당하지 않습니다.",
