  "explain": "📖 교재 근거:\n| 신속보고 | 화장품책임판매업자 | • 중대한 유해사례, 판매중지나 회수에 준하는 외국정부의 조치 또는 이와 관련하여 식품의약품안전처장이 보고를 지시한 경우<br>• 안전성 정보를 알게 된 날로부터 15일 이내 식품의약품안전처장에게 보고 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제품 사용 중단 시 증상이 호전되고 재사용 시 동일 증상이 재발하여 가장 확실한 인과관계로 판단하는 등급은 ④ '확실함(Certain)'이 정답입니다. 따라서 이보다 연관성이 낮거나 평가가 다른 단계에 해당하는 ① 의심스러움, ② 가능성 높음, ③ 가능성 있음, ⑤ 평가 불가는 오답입니다.",
