  "derivedFrom": "subject2_q85",
  "explain": "📖 법령 근거 (L739):\n④ 식품의약품안전처장은 제출된 자료를 평가하고 별표 2에 따른 실태조사를 실시하여 우수화장품 제조 및 품질관리기준 적합판정한 경우에는 별지 제3호 서식에 따른 우수화장품 제조 및 품질관리기준 적합업소 증명서를 발급하여야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 주어진 정답에 따라 일탈이 발생했을 때 현장 작업자가 임의로 조치하거나 기록을 생략한 채 작업을 속행해서는 안 되므로 ⑤번은 옳지 않은 설명입니다. 따라서 일탈 관리에 대한 설명으로 옳지 않은 것을 고르는 해당 문제의 정답은 ⑤번입니다.",
