  "derivedFrom": "subject2_q86",
  "explain": "📖 교재 근거:\n| 메칠이소치아졸리논 | Methylisothiazolinone | 방부제 | - | 화장품의 변질을 막고 보존력을 높이는 방부제로, 0.0015% 이하로 사용이 제한된 성분입니다. | - | 사용 후 씻어내는 제품에 0.0015% (단, 메칠클로로이소치아졸리논과 메칠이소치아졸리논 혼합물과 병행 사용금지) | 방부·보존 | 고빈도 | 기타 제품에는 사용금지 | - |\n해설: '메칠클로로이소치아졸리논(MCI)과 메칠이소치아졸리논(MI) 혼합물'의 고시상 규정된 배합 성비(MCI : MI)는 3 : 1이므로 ⑤번이 정답입니다. 따라서 다른 비율(1 : 1, 2 : 1, 10 : 1, 5 : 1)을 제시한 선지 ①, ②, ③, ④는 틀린 설명입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
  "answer": "4"
