  "explain": "📖 교재 근거:\n| 부틸메톡시디벤조일메탄 | Butyl Methoxydibenzoylmethane | 자외선 차단제 | - | 유상층에 용해되어 자외선 흡수에 관여하며, 사용 제한이 있는 자외선 차단 관련 성분입니다. | - | 5.0% | 홍조, 색소침착 | 고빈도 | UVA 차단 | - |\n해설: 부틸메톡시디벤조일메탄(아보벤존)은 유상층에 용해되어 자외선 흡수에 관여하며 자외선 A(UVA)를 차단하는 성분입니다. 반면 호모살레이트는 자외선 B(UVB)를 차단하는 성분이므로 정답이 아닙니다.",
