  "derivedFrom": "subject2_q88",
  "explain": "📖 교재 근거 (L2899):\n#### 제모제 🎯 기출 (치오글라이콜릭애씨드 함유 제품에만 표시함) — 사용금지: ① 생리 전후·산전·산후·병후 ② 얼굴·상처·부스럼·습진·짓무름·염증·반점·자극 피부 ③ 유사 제품 부작용 피부 ④ 약한 피부·남성 수염 부위\n해설: 치오글라이콜릭애씨드 함유 제모제의 사용금지 대상에는 생리 전후·산전·산후·병후의 환자(①), 얼굴·상처·습진 등 염증이나 자극이 있는 피부(②), 유사 제품 부작용 병력이 있는 피부(③), 약한 피부나 남성의 수염 부위(④) 등이 포함되므로 이들은 오답입니다. 반면 건강한 팔·다리의 털이 있는 부위(⑤)는 사용금지 대상에 해당하지 않으므로 정답입니다.",
