  "derivedFrom": "subject2_q95",
  "explain": "📖 교재 근거:\n| 장벽대체제 | 각질층 내 세포간지질(세라마이드, 지방산, 콜레스테롤) 성분으로 보습제 성분으로 처방하여 피부장벽 기능의 유지와 회복에 관여함으로써 피부 보습력 유지를 증가시킴 |\n해설: 각질층 내 세포간지질은 세라마이드, 지방산, 콜레스테롤로 구성되어 피부장벽 기능의 유지와 회복에 관여하며, 유탁액 부형제로는 물, 오일, 유화제 등이 사용되므로 극성이 없는 광물성 오일만을 100% 사용하여 유화하는 것은 적절하지 않아 ⑤번이 정답입니다. 반면 세포간지질 성분을 배합하고 유화제와 물, 오일 등을 활용해 유화 구조와 안정성을 유지하는 배합 방식은 올바른 설계 요소입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
  "answer": "1"
