  "derivedFrom": "subject2_q96",
  "explain": "📖 교재 근거:\n• 내수성·지속내수성은 측정 결과에 근거하여 내수성비 신뢰구간이 50% 이상일 때, '내수성' 또는 '지속내수성'으로 표시한다.\n해설: 자외선A 차단등급(PA)은 자외선 A(UVA)를 차단하는 효과의 등급을 나타내므로 ③번이 옳습니다. 반면 자외선 B(UVB)를 차단하는 지수나 숫자로 표시하는 것은 자외선 차단지수(SPF)에 해당하므로 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
  "answer": "3"
