  "derivedFrom": "subject2_q97",
  "explain": "📖 교재 근거:\n| 점증제 | 화장품의 점도를 높여주는 화합물, 수용성 고분자 물질 제품의 사용감과 안정성을 향상시키기 위해 사용 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 모세관 속을 유체가 자중(무게)으로 흘러내리는 시간을 측정하여 점도를 측정하는 점도계는 캐논-펜스케(Cannon-Fenske) 모세관 점도계이므로 ①이 정답입니다. 브룩필드 점도계, 회전식 점도계, 원판 점도계, 초음파 점도계 등은 해당 측정 방식에 해당하지 않으므로 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
  "answer": "1"
