  "derivedFrom": "subject2_q106",
  "explain": "📖 법령 근거 (L184):\n③ 제조시설이나 설비의 세척에 사용되는 세제 또는 소독제는 효능이 입증된 것을 사용하고 잔류하거나 적용하는 표면에 이상을 초래하지 아니하여야 한다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 우수화장품 제조 및 품질관리기준 제9조 제3항에 따르면 제조시설 및 설비의 세척 시 사용된 세제나 소독제 등이 잔류하지 않아야 하므로 관련 성분의 잔류 여부를 검증해야 합니다. 따라서 기계 모터의 교류 전기 주파수(①)는 세척 후 표면에서 검증하는 잔류 평가 성분에 해당하지 않으므로 올바른 정답입니다.",
