  "explain": "📖 교재 근거 (restricted_ingredients):\n| 알킬이소퀴놀리늄브로마이드 | Alkyl Isoquinolinium Bromide | 방부제 | - | 화장품의 변질을 방지하는 방부제로, 0.05% 이하로 사용이 제한되는 성분입니다. | - | 사용 후 씻어내지 않는 제품에 0.05% | 방부·보존 | 저빈도 | 알킬화합물 | - |\n해설: 화장품의 사용 제한 보존제 성분 중 클로로자이레놀의 최대 사용 한도는 0.5% 이하이므로 정답은 ②입니다. 따라서 0.1% 이하(①), 0.3% 이하(③), 1.0% 이하(④), 배합 금지(⑤)를 제시한 선지들은 옳지 않습니다.",
