  "derivedFrom": "subject2_q120",
  "explain": "📖 교재 근거:\n```mermaid\nmindmap\nroot((Ch01<br/>화장품 원료의 종류와 특성))\n원료 분류\n수성 원료\n정제수·알코올·보습제 폴리올\n유성 원료\n유동파라핀·스쿠알란·에스터류·실리콘유\n계면활성제\n음이온성·양이온성·비이온성·양쪽성\n첨가제\n해설: 글리세린은 화장품 수성 원료 중 보습제(폴리올)로 분류되므로 주요 기능은 보습제(①)입니다. 따라서 방부제(②), 자외선차단제(③), 산화방지제(④), 착색제(⑤)는 글리세린의 주요 기능에 해당하지 않아 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
