  "explain": "📖 교재 근거:\n| 정제수 | • 화장품 제조에 있어 가장 중요한 원료 중 하나임<br>• 물은 극성물질로 수성 원료의 용해를 위한 용제(용매)로 사용<br>• 용해된 이온, 고체 입자, 미생물, 유기물 및 용해된 기체류 등의 모든 불순물을 이온교환수지를 통해 여과한 물을 칭함 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품에서 수성 원료의 용해를 위한 용제(용매)로 사용되는 원료의 명칭은 ⑤ 물(Water)입니다. 반면 ① 정제수는 불순물을 이온교환수지를 통해 여과한 물을 칭하는 것이며, 수돗물·증류수·탈이온수 등은 해당 명칭과 일치하지 않아 오답입니다.",
  "source": "화장품 제조 및 품질관리 (370제)",
