  "explain": "📖 교재 근거:\n> - 4과목 6챕터 \"혼합 및 소분\" — 원료 분류(수성/유성/계면활성제)의 요약 재서술 및 혼합 안정성 응용\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품의 가속 안정성 시험은 일반적으로 ②번과 같이 40℃ ~ 50℃의 조건에서 1~3개월 동안 진행하여 안정성을 평가합니다. 따라서 저온 조건이나 실온, 100℃ 이상의 극단적인 조건을 제시한 ①, ③, ④, ⑤번은 올바른 가속 안정성 시험 조건에 해당하지 않습니다.",
