  "explain": "📖 교재 근거:\n| 유효 성분 | 화장품에 특별한 효능을 부여하기 위해 사용하는 물질로 각 제품의 특징을 나타내는 역할을 함 (예: 미백, 주름 개선 및 자외선 차단 성분 등) |\n해설: 제공된 정답에 따라 레티놀(비타민 A)의 주요 기능성 효과는 주름개선(②)입니다. 따라서 미백, 자외선 차단, 여드름 완화, 탈모 방지를 제시한 나머지 선지는 이에 해당하지 않아 오답입니다.",
