  "explain": "📖 교재 근거:\n- 유화에 영향을 미치는 요인: 유화제(종류와 사용량), 원료의 성질, 유화 조건(성분 첨가 순서, 교반속도, 온도, 유화장치 등)\n해설: 유화 온도, 교반 속도, 분산상(내상)과 연속상(외상)의 비율, 유화제의 종류 등은 유화 및 점도에 영향을 미치는 요인에 해당합니다. 반면, 제품의 판매 가격은 유화에 영향을 미치는 요인에 포함되지 않으므로 가장 큰 영향을 미치는 인자가 아닙니다.",
