  "explain": "📖 교재 근거:\n| CGMP | 우수화장품 제조 및 품질관리 기준(Cosmetic Good Manufacturing Practice). 4대 기준서로 구성. 제조업 의무 적용. |\n해설: 우수화장품 제조 및 품질관리 기준(CGMP)의 4대 기준서는 제품표준서, 제조관리기준서, 품질관리기준서, 제조위생관리기준서로 구성됩니다. 따라서 원료관리기준서(②)는 4대 기준서에 해당하지 않으며, 나머지 선지(①, ③, ④, ⑤)는 모두 4대 기준서에 포함됩니다.",
