  "derivedFrom": "subject2_q282",
  "explain": "📖 교재 근거:\n| 제모 | 치오글리콜산 80% | 산으로서 3.0~4.5%, pH 7.0~12.7 | 로션, 액제, 크림, 에어로졸 |\n해설: 규정에 따르면 제모 기능을 가진 화장품의 대표 성분 및 기준 규격은 '치오글리콜산 80% — 산으로서 3.0~4.5%, pH 7.0~12.7'이므로 ①이 정답입니다. 살리실릭애씨드는 여드름 완화, 아데노신은 주름 개선, p-페닐렌디아민은 염모, 징크옥사이드는 자외선 차단 관련 성분이므로 제모 기능에 해당하지 않습니다.",
