  "derivedFrom": "subject2_q288",
  "explain": "📖 교재 근거:\n> 정답: ④\n> 해설: 50mL(g) 이하의 포장일 경우 전성분 표시를 생략할 수 있다(단, 속눈썹용 퍼머넌트 웨이브 제품과 외음부 세정제 등 일부 소용량 화장품은 용량에 관계없이 기재해야 한다).\n해설: 50mL(g) 이하의 포장일 경우 원칙적으로 전성분 표시를 생략할 수 있다. 단, 속눈썹용 퍼머넌트 웨이브 제품이나 외음부 세정제 등 일부 특정 소용량 화장품은 용량에 관계없이 기재해야 한다.",
