  "explain": "📖 교재 근거:\n- HLB 값 🔖기출: 3~6 = W/O 유화제, 8~18 = O/W 유화제, 15~18 = 가용화제 (높을수록 친수성)\n해설: HLB 값은 높을수록 친수성이며, 3~6은 W/O 유화제, 8~18은 O/W 유화제, 15~18은 가용화제로 주로 사용된다. 따라서 HLB 값이 15~18일 때 가용화제로 쓰인다는 설명이 옳다.",
