  "explain": "📖 교재 근거:\n| 연화제(유연제) | 각질세포 사이 틈을 메워 윤기·유연성 제공. 오일류, 에스터. |\n해설: 연화제(유연제)는 각질세포 사이의 틈을 메워 윤기와 유연성을 제공하므로 정답은 ①입니다. 반면 밀폐제는 소수성 피막을 형성해 경피수분손실량(TEWL)을 저하시키고, 습윤제는 수분 결합을 통해 피부 수분을 증가시키며, 장벽대체제는 피부장벽 기능 유지 및 회복을 돕는 성분입니다.",
