  "explain": "📖 교재 근거:\n| 장벽대체제 | 세라마이드·지방산·콜레스테롤. 피부장벽 기능 유지·회복. |\n해설: 폴리올은 -OH기가 2개 이상인 유기화합물로 글리세린(3가), BG(2가) 등이 해당하며, 습윤제로서 케라틴 및 NMF와 수분을 결합시켜 피부 수분을 증가시킵니다. 반면 세라마이드와 콜레스테롤은 폴리올이 아니라 피부장벽 기능 유지 및 회복을 돕는 장벽대체제에 해당하므로 ⑤번이 옳지 않습니다.",
