  "explain": "📖 교재 근거:\n#### 2.2 원자재, 반제품 및 벌크제품은 바닥과 벽에 닿지 않도록 보관하고, 가능한 선입선출에 의해 출고될 수 있도록 보관해야 한다.\n해설: 원자재, 반제품 및 벌크제품은 바닥과 벽에 닿지 않도록 보관하고 가능한 선입선출에 의해 출고될 수 있도록 보관해야 하므로 ③번이 옳습니다. 바닥·벽에 밀착하거나(①) 최근 입고 제품부터 출고하는 것(②)은 잘못되었으며, 보관기한을 반드시 설정해야 하고(④) 기한이 지난 경우 재평가 시스템을 거치도록 규정하고 있으므로(⑤) 나머지 선지는 모두 틀렸습니다.",
