  "explain": "📖 교재 근거:\n• 재고 회전은 선입선출 방식으로 사용 및 유통\n해설: 수동 또는 전산화 시스템에 따라 재고 회전은 선입선출 방식으로 사용 및 유통되어야 한다. 재질 및 제품의 수령과 철회는 적절히 허가되어야 하며(L2739), 파레트 적재 재료에는 불출 상태 및 필요한 경우 보관 조건을 표시해야 한다(L2746~L2747).",
