  "derivedFrom": "subject2_q363",
  "explain": "📖 교재 근거:\n#### 1.3 직사광선을 피하고 서늘하고 그늘지며 건조한 곳에 보관한다. 보존제를 함유하지 않은 화장품은 오염을 최소화하기 위해 냉장 보관하는 것이 좋다.\n해설: 보존제를 함유하지 않은 화장품은 오염을 최소화하기 위해 온열 보관이 아닌 냉장 보관하는 것이 좋으므로 ③번이 옳지 않은 설명입니다. ①, ②, ④, ⑤번은 모두 교재의 화장품 보관 및 취급 방법에 부합하는 올바른 설명입니다.",
