  "explain": "📖 교재 근거:\n#### 1.5 사용되는 도구는 항상 청결을 유지(중성 세제 사용)한다. 세척 후에는 완전히 건조시킨 후 사용하는 것이 좋다.\n해설: 화장품에 사용되는 도구는 중성 세제를 사용하여 항상 청결을 유지해야 하므로 ②번이 옳습니다. 또한 세척 후에는 완전히 건조시킨 후 사용하는 것이 좋으므로, 강산성 세제를 사용하거나 물기가 남은 상태로 사용·보관한다는 설명은 적절하지 않습니다.",
