  "explain": "📖 교재 근거:\n#### 1.6 매니큐어, 마스카라, 리퀴드 아이라이너 등은 공기가 들어가면 쉽게 굳으므로 용기 내에서 잦은 펌핑을 주의한다.\n해설: 매니큐어, 마스카라, 리퀴드 아이라이너 등은 공기가 들어가면 쉽게 굳으므로 용기 내에서 잦은 펌핑을 주의해야 합니다. 따라서 잦은 펌핑을 권장한다는 ①번은 틀린 설명이며, 제품에 물 등 액체를 넣으면 세균이 쉽게 자랄 수 있으므로 물을 섞어 쓴다는 ③번 또한 옳지 않습니다.",
