  "explain": "📖 교재 근거:\n#### 1.7 사용기한이 표시된 제품은 표시 기간 내에 사용하고, 내용물에 이상이 생겼을 경우에는 사용을 금지한다.\n해설: 눈이 감염되어 있는 경우 눈 화장은 피해야 하며, 알레르기나 피부 자극이 일어나면 즉시 사용을 중지하고 중지 후에도 이상 반응이 지속되면 전문의사와 상담해야 한다. 또한 사용기한이 표시된 제품은 표시 기간 내에 사용해야 한다.",
